"use client";

import * as React from "react";
import { Composer } from "../composer/composer.js";
import { Message } from "../message/message.js";
import { MessageList } from "../message-list/message-list.js";
import { Shimmer } from "../shimmer/shimmer.js";
import { Sources, type SourceRef } from "../sources/sources.js";
import { cn } from "../../lib/utils.js";

/**
 * Speaker of a message. Mirrors the canonical `Role` union from
 * `@hex-core/components` exactly — kept inline (rather than imported
 * from `../types.js`) so the registry CLI distribution path (`npx hex
 * add conversation`) ships a self-contained file. Same precedent as
 * `task.tsx`'s inlined `ToolCallState`. The build-registry script
 * doesn't bundle `types.ts`, so importing from it would leave consumer
 * TS strict-mode unable to resolve the type at the install location.
 */
type Role = "user" | "assistant" | "system" | "tool";

/**
 * High-level chat shell. Composes `<MessageList>` over `messages`, an
 * optional `<Sources>` panel beneath the latest assistant turn, an
 * optional `<Shimmer>` placeholder for the in-flight assistant response,
 * and a `<Composer>` row at the bottom.
 *
 * Presentational: the consumer owns the `messages` array and the
 * `onSubmit` handler. The composer's text state is internal by default
 * so simple consumers don't thread input plumbing; pass `value` +
 * `onValueChange` together to take full control (suggested-prompt
 * injection, voice transcription, form-library integration).
 *
 * @example
 * <Conversation
 *   messages={messages}
 *   onSubmit={(text) => sendMessage(text)}
 *   isStreaming={isWaitingForFirstToken}
 *   sources={lastResponse.sources}
 *   placeholder="Ask anything…"
 * />
 */
export interface ConversationProps {
	/** Ordered chat history. Each item renders as one `<Message>`. */
	messages: ConversationMessage[];
	/** Called with the trimmed text when the user submits the composer. */
	onSubmit: (text: string) => void;
	/** Composer placeholder. */
	placeholder?: string;
	/** Controlled composer text. Pass with `onValueChange` to take control of the input — useful for suggested prompts, voice transcripts, or form-library integration. */
	value?: string;
	/** Called whenever the composer text changes. Required when `value` is set. */
	onValueChange?: (value: string) => void;
	/** When true, render a `<Shimmer>` placeholder above the composer (use during the dead time before the first stream token). */
	isStreaming?: boolean;
	/** Optional citations rendered as a `<Sources>` panel beneath the message stream. */
	sources?: SourceRef[];
	/** Disable the composer (e.g. while waiting on a tool call). */
	disabled?: boolean;
	/** Trailing slot inside the composer — typically a Send button. */
	composerActions?: React.ReactNode;
	className?: string;
}

/** A single message in a `<Conversation>`. */
export interface ConversationMessage {
	/** Stable identifier — used for the React key. */
	id: string;
	/** Speaker. */
	role: Role;
	/** Message content. Pass a string for plain text or a node (e.g. `<Markdown>`) for formatted output. */
	content: React.ReactNode;
}

/**
 * Render a chat conversation shell.
 * @param props - messages + submit handler + optional streaming/sources state
 * @returns A flex column with a scrolling message list, optional sources/shimmer, and a composer row
 */
function Conversation({
	messages,
	onSubmit,
	placeholder = "Ask anything…",
	value: valueProp,
	onValueChange: onValueChangeProp,
	isStreaming = false,
	sources,
	disabled = false,
	composerActions,
	className,
}: ConversationProps) {
	const [internalValue, setInternalValue] = React.useState("");
	const isControlled = valueProp !== undefined;
	const value = isControlled ? valueProp : internalValue;
	const setValue = isControlled
		? (next: string) => onValueChangeProp?.(next)
		: setInternalValue;

	if (
		process.env.NODE_ENV !== "production" &&
		isControlled &&
		typeof onValueChangeProp !== "function"
	) {
		// Surface the controlled-mode contract at runtime — `value` without
		// `onValueChange` makes the textarea silently read-only, which is a
		// frustrating debug. Schema commonMistakes flags it too, but a console
		// nudge catches it in the dev loop.
		console.error(
			"<Conversation>: `value` was passed without `onValueChange`. The composer will be read-only — pass both props together for controlled mode, or omit both to let the component manage state internally.",
		);
	}

	function handleSubmit(text: string) {
		onSubmit(text);
		setValue("");
	}

	return (
		<div className={cn("flex h-full min-h-0 flex-col gap-3", className)}>
			<MessageList className="min-h-0 flex-1">
				{messages.map((m) => (
					<Message key={m.id} role={m.role}>
						{m.content}
					</Message>
				))}
				{isStreaming ? (
					<Message role="assistant">
						<Shimmer width="60%" />
					</Message>
				) : null}
			</MessageList>
			{sources && sources.length > 0 ? <Sources sources={sources} /> : null}
			<Composer
				value={value}
				onValueChange={setValue}
				onSubmit={handleSubmit}
				disabled={disabled}
				placeholder={placeholder}
			>
				{composerActions}
			</Composer>
		</div>
	);
}

export { Conversation };

/**
 * Color conversion utilities for the HSL-triplet token format used across
 * `@hex-core/tokens` themes (`H S% L%`, e.g. `"240 5.9% 10%"` — no `hsl()`
 * wrapper, no commas).
 *
 * The triplet is the round-trip-safe serialization for Hex UI: tokens flow
 * triplet → CSS `hsl(var(--token))` → rendered color, and the ColorPicker
 * component edits triplets directly. Hex/RGB conversions are display
 * adapters, not the source of truth.
 */

/** Parsed HSL components. `h` is degrees (0–360); `s` and `l` are percentages (0–100). */
export interface HslTriplet {
	h: number;
	s: number;
	l: number;
}

/** Parsed RGB components. Each channel is 0–255. */
export interface RgbColor {
	r: number;
	g: number;
	b: number;
}

/**
 * Parse an HSL triplet string into numeric components.
 *
 * Note: malformed input silently coerces to `{0,0,0}` (pure black) rather than
 * returning an error signal. Callers that need to distinguish "user typed
 * black" from "user typed garbage" should validate the input format first.
 * `hexToHslTriplet` returns `null` for malformed hex; this asymmetry is
 * intentional — triplets feed CSS variables where any non-color value would
 * already break rendering.
 *
 * @param triplet - String in the form `"<H> <S>% <L>%"` (e.g. `"240 5.9% 10%"`).
 * @returns Numeric components, or `{0,0,0}` if the input is malformed.
 */
export function parseHslTriplet(triplet: string): HslTriplet {
	const parts = triplet.trim().split(/\s+/);
	return {
		h: Number.parseFloat(parts[0]) || 0,
		s: Number.parseFloat(parts[1]) || 0,
		l: Number.parseFloat(parts[2]) || 0,
	};
}

/**
 * Format HSL components into an HSL triplet string (the canonical token format).
 * @param hsl - Numeric components.
 * @returns Triplet in the form `"<H> <S>% <L>%"`.
 */
export function formatHslTriplet({ h, s, l }: HslTriplet): string {
	// Tolerant integer check: rgbToHsl can produce values like 5.0000000001 due
	// to float arithmetic; format those as "5" rather than "5.0".
	const round = (n: number) =>
		Math.abs(n - Math.round(n)) < 1e-6 ? `${Math.round(n)}` : n.toFixed(1);
	return `${Math.round(h)} ${round(s)}% ${round(l)}%`;
}

/**
 * Convert HSL components to RGB.
 * @param h - Hue (0–360).
 * @param s - Saturation (0–100).
 * @param l - Lightness (0–100).
 * @returns RGB channels (0–255, rounded).
 */
export function hslToRgb(h: number, s: number, l: number): RgbColor {
	const sN = s / 100;
	const lN = l / 100;
	const k = (n: number) => (n + h / 30) % 12;
	const a = sN * Math.min(lN, 1 - lN);
	const f = (n: number) => lN - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
	return {
		r: Math.round(255 * f(0)),
		g: Math.round(255 * f(8)),
		b: Math.round(255 * f(4)),
	};
}

/**
 * Convert RGB components to HSL.
 * @param r - Red (0–255).
 * @param g - Green (0–255).
 * @param b - Blue (0–255).
 * @returns HSL components (h: 0–360, s: 0–100, l: 0–100).
 */
export function rgbToHsl(r: number, g: number, b: number): HslTriplet {
	const rN = r / 255;
	const gN = g / 255;
	const bN = b / 255;
	const max = Math.max(rN, gN, bN);
	const min = Math.min(rN, gN, bN);
	let h = 0;
	let s = 0;
	const l = (max + min) / 2;
	if (max !== min) {
		const d = max - min;
		s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
		if (max === rN) h = (gN - bN) / d + (gN < bN ? 6 : 0);
		else if (max === gN) h = (bN - rN) / d + 2;
		else h = (rN - gN) / d + 4;
		h /= 6;
	}
	return { h: h * 360, s: s * 100, l: l * 100 };
}

/**
 * Convert an HSL triplet to a 6-digit hex string.
 * @param triplet - HSL triplet (e.g. `"240 5.9% 10%"`).
 * @returns Lowercase hex string with leading `#` (e.g. `"#181a1f"`).
 */
export function hslTripletToHex(triplet: string): string {
	const { h, s, l } = parseHslTriplet(triplet);
	const { r, g, b } = hslToRgb(h, s, l);
	const toHex = (n: number) => n.toString(16).padStart(2, "0");
	return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

/**
 * Convert a hex string to an HSL triplet.
 * Accepts 3-digit (`#abc`) or 6-digit (`#aabbcc`) hex with optional `#`.
 * @param hex - Hex color string.
 * @returns HSL triplet, or `null` if the input is malformed.
 */
export function hexToHslTriplet(hex: string): string | null {
	const clean = hex.trim().replace(/^#/, "");
	let normalized: string;
	if (/^[0-9a-fA-F]{3}$/.test(clean)) {
		normalized = clean
			.split("")
			.map((c) => c + c)
			.join("");
	} else if (/^[0-9a-fA-F]{6}$/.test(clean)) {
		normalized = clean;
	} else {
		return null;
	}
	const r = Number.parseInt(normalized.slice(0, 2), 16);
	const g = Number.parseInt(normalized.slice(2, 4), 16);
	const b = Number.parseInt(normalized.slice(4, 6), 16);
	return formatHslTriplet(rgbToHsl(r, g, b));
}

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with Tailwind CSS conflict resolution.
 * @param inputs - Class values (strings, arrays, objects) to merge
 * @returns A single merged class string with Tailwind conflicts resolved
 */
export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

